INSERT INTO LAFT_CLEP_AUDIT_SURVEY_FORM (PFI, SURVEY_DATE, SURVEYOR, RECEIVE_DATE, INST_BASED_REPORTABLE_HIV, LAB_USES_ECLRS, LAB_USES_REF_LAB, REFERENCE_PFI, CREATE_UID, CREATE_DATE)
VALUES (
	upper(#{userEnteredPfi,jdbcType=VARCHAR})
	, FN_TO_DATE(#{labDateOfSurvey,jdbcType=DATE},'MM/DD/YYYY')
	, trim(upper(#{labSurveyorName,jdbcType=VARCHAR})) 
	, FN_TO_DATE(#{faxReceivedDate,jdbcType=DATE},'MM/DD/YYYY')
	, #{insBasedHivTest,jdbcType=VARCHAR}
	, #{rptNysDohByEclrs,jdbcType=VARCHAR}
	, #{labRefLabForTest,jdbcType=VARCHAR}
	, upper(#{labRefPFI,jdbcType=VARCHAR})
	, upper(#{clepUserId,jdbcType=VARCHAR})
	, SYSDATE
)

