UPDATE LAFT_CLEP_AUDIT_SURVEY_FORM
SET REVIEW_COMPLETED = 'Yes', REVIEW_COMPLETED_BY = #{surveyReviewedBy,jdbcType=VARCHAR},	REVIEW_COMPLETED_DATE = SYSDATE
WHERE SURVEY_NUMBER = #{surveyNo}

UPDATE LAFT_CLEP_AUDIT_SURVEY_UPLOAD
SET ASSIGNED_STAFF_ID = #{assignedStaffId,jdbcType=VARCHAR}, ASSIGNED_DATE = FN_TO_DATE(#{assignedDate,jdbcType=DATE},'MM/DD/YYYY'),
	ASSIGNED_BY = #{assignedBy,jdbcType=VARCHAR}, SURVEY_CLOSE_DATE = FN_TO_DATE(#{surveyCloseDate,jdbcType=DATE},'MM/DD/YYYY'), 
	SURVEY_CLOSE_BY = #{surveyCloseBy,jdbcType=VARCHAR}, COMMENTS = #{comments,jdbcType=VARCHAR}
WHERE PFI_UPLOAD_PK = #{uploadNumber}

UPDATE LAFT_CLEP_AUDIT_SURVEY_FORM
SET RECRUIT_ASSESS_STAFF_ASSIGN = #{recruitAssessStaffAssign,jdbcType=VARCHAR}, RECRUIT_ASSESS_DATE_ASSIGN = FN_TO_DATE(#{recruitAssessDateAssign,jdbcType=DATE},'MM/DD/YYYY'),
	RECRUIT_ASSESS_STAFF_ASSIGN_BY = #{recruitAssessStaffAssignBy,jdbcType=VARCHAR}, RECRUIT_ASSESS_DATE_COMPLETE = FN_TO_DATE(#{recruitAssessDateComplete,jdbcType=DATE},'MM/DD/YYYY'), 
	RECRUIT_ASSESS_STAFF_COMPLETE = #{recruitAssessStaffComplete,jdbcType=VARCHAR}, RECRUIT_ASSESS_OUTCOME = #{recruitAssessOutcome,jdbcType=VARCHAR},
	RECRUIT_ASSESS_COMMENTS = #{recruitAssessComments,jdbcType=VARCHAR}
WHERE SURVEY_NUMBER = #{surveyNumber}
